package com.example.orders;

import java.math.BigDecimal;
import java.util.List;

public final class OrderCalculator {

    public record Line(String sku, int quantity, BigDecimal unitPrice) { }

    private OrderCalculator() { }

    public static BigDecimal total(List<Line> lines) {
        BigDecimal sum = BigDecimal.ZERO;
        for (Line line : lines) {
            if (line.quantity() <= 0) {
                throw new IllegalArgumentException("quantity must be positive: " + line.sku());
            }
            sum = sum.add(line.unitPrice().multiply(BigDecimal.valueOf(line.quantity())));
        }
        return sum;
    }
}

package com.example.orders;
import com.example.orders.OrderCalculator.Line;
import java.math.BigDecimal;
import java.util.List;
public class OrderCalculatorTest {
    static int failures = 0;
    static void check(String name, boolean condition) {
        System.out.println((condition ? "PASS " : "FAIL ") + name);
        if (!condition) {
            failures++;
        }
    }

    public static void main(String[] args) {
        List<Line> lines = List.of(
            new Line("BOOK-1", 2, new BigDecimal("12.50")),
            new Line("PEN-7", 3, new BigDecimal("1.20")));
        check("total of two lines is 28.60",
            OrderCalculator.total(lines).compareTo(new BigDecimal("28.60")) == 0);
        check("empty order totals zero",
            OrderCalculator.total(List.of()).compareTo(BigDecimal.ZERO) == 0);
        boolean rejected = false;
        try {
            OrderCalculator.total(List.of(new Line("BAD", 0, BigDecimal.ONE)));
        } catch (IllegalArgumentException e) {
            rejected = true;
        }
        check("zero quantity is rejected", rejected);
        if (failures > 0) {
            System.out.println(failures + " test(s) failed");
            System.exit(1);
        }
    }
}

