pipeline {
    agent none
    options {
        timeout(time: 45, unit: 'MINUTES')
        buildDiscarder(logRotator(numToKeepStr: '20'))
        disableConcurrentBuilds(abortPrevious: true)
        timestamps()
    }
    environment {
        REGISTRY = 'ghcr.io/example'
        IMAGE    = 'orders-service'
    }
    stages {
        stage('CI') {
            agent { label 'maven-jdk21' }
            stages {
                stage('Build and test') {
                    steps {
                        sh './mvnw -B verify'
                    }
                    post {
                        always {
                            junit testResults: '**/target/*-reports/TEST-*.xml'
                        }
                    }
                }
                stage('Analysis') {
                    parallel {
                        stage('SonarQube') {
                            steps {
                                withSonarQubeEnv('sonar-server') {
                                    sh './mvnw -B sonar:sonar'
                                }
                            }
                        }
                        stage('Dependency check') {
                            steps {
                                sh './mvnw -B org.owasp:dependency-check-maven:check'
                            }
                        }
                    }
                }
                stage('Quality gate') {
                    steps {
                        timeout(time: 10, unit: 'MINUTES') {
                            waitForQualityGate abortPipeline: true
                        }
                    }
                }
                stage('Image') {
                    when {
                        branch 'main'
                        beforeAgent true
                    }
                    steps {
                        script {
                            env.IMAGE_TAG = sh(script: 'git rev-parse --short=7 HEAD',
                                               returnStdout: true).trim()
                        }
                        withCredentials([usernamePassword(credentialsId: 'ghcr-push',
                                usernameVariable: 'REG_USER', passwordVariable: 'REG_PASS')]) {
                            sh '''
                                echo "$REG_PASS" | docker login ghcr.io \
                                    -u "$REG_USER" --password-stdin
                                docker build -t "$REGISTRY/$IMAGE:$IMAGE_TAG" .
                                docker push "$REGISTRY/$IMAGE:$IMAGE_TAG"
                            '''
                        }
                    }
                }
            }
        }
        stage('Deploy staging') {
            when {
                branch 'main'
                beforeAgent true
            }
            agent { label 'deploy' }
            steps {
                withCredentials([file(credentialsId: 'kubeconfig-staging',
                                 variable: 'KUBECONFIG')]) {
                    sh 'kubectl set image deploy/orders-service app="$REGISTRY/$IMAGE:$IMAGE_TAG"'
                    sh 'kubectl rollout status deploy/orders-service --timeout=180s'
                }
            }
        }
        stage('Approve production') {
            when {
                branch 'main'
                beforeInput true
            }
            options { timeout(time: 24, unit: 'HOURS') }
            input {
                message 'Deploy this build to production?'
                ok 'Deploy'
                submitter 'release-managers'
            }
            steps {
                echo 'Approved'
            }
        }
        stage('Deploy production') {
            when {
                branch 'main'
                beforeAgent true
            }
            agent { label 'deploy' }
            steps {
                withCredentials([file(credentialsId: 'kubeconfig-prod',
                                 variable: 'KUBECONFIG')]) {
                    sh 'kubectl set image deploy/orders-service app="$REGISTRY/$IMAGE:$IMAGE_TAG"'
                    sh 'kubectl rollout status deploy/orders-service --timeout=180s'
                }
            }
        }
    }
    post {
        failure { echo 'Build failed: notify the team channel here' }
    }
}

